"""Controller-driven shared-inventory and authoritative grenade flight checks."""
import json,time,math
from pathlib import Path
from run_acceptance import *
results=[]
def test(name,predicate,seconds=12):
 d=wait_for(predicate,seconds);results.append({'name':name,'passed':True,'observed':d});Path('Saved/EquipmentQA/merc-grenades.json').write_text(json.dumps(results,indent=2));print('PASS',name,flush=True);return d
def live(w):return [g for g in w['grenades'] if not g['exploded']]
def all_stock(d,index,count):return synced(d,index,lambda p:p['mercGrenades']==count)
def grab():
 action(0,'takedown_rear');time.sleep(.6);pad(2,'x');test('spy grabs the throwing merc',lambda d:synced(d,2,lambda p:p['captor']) and synced(d,1,lambda p:p['restrained']))
def extended():action(2,'pad_rt_down');time.sleep(.75);action(2,'pad_rt_up')
def merc_ready():test('merc respawns with two shared grenades',lambda d:synced(d,1,lambda p:p['health']==100 and p['mercGrenades']==2),15)
try:
 stop();call(project_tool,'open_map',map_name='Prototype');start(1);pad(0,'gadget')
 test('spy cannot throw a merc grenade',lambda d:local_pawn(d)['spy'] and not live(server(d)))
 pad(0,'role');test('solo merc starts with two grenades',lambda d:not local_pawn(d)['spy'] and local_pawn(d)['mercGrenades']==2)
 action(0,'place_open');time.sleep(.5);action(0,'pad_gadget_down');time.sleep(.15);action(0,'pad_gadget_up')
 d=test('RB throws one grenade and spends one shared charge',lambda d:local_pawn(d)['mercGrenades']==1 and len(live(server(d)))==1 and live(server(d))[0]['thrown'])
 origin=live(server(d))[0]
 time.sleep(.4)
 test('grenade actually travels forward on its projectile arc',lambda d:len(live(server(d)))==1 and live(server(d))[0]['x']>origin['x']+150)
 test('grenade bounces off level geometry',lambda d:any(g['bounces']>0 for g in live(server(d))),3)
 test('thrown grenade detonates on its original fuse',lambda d:not live(server(d)) and local_pawn(d)['mercGrenades']==1,6)
 pad(0,'y');test('Y holsters without replenishing grenades',lambda d:local_pawn(d)['equipment']['weapon']==0 and local_pawn(d)['mercGrenades']==1)
 action(0,'pad_gadget_down');time.sleep(.9)
 test('holding RB throws once while carbine is holstered',lambda d:local_pawn(d)['mercGrenades']==0 and len(live(server(d)))==1 and local_pawn(d)['equipment']['weapon']==0)
 action(0,'pad_gadget_up');test('last grenade clears after fuse',lambda d:not live(server(d)),6)
 pad(0,'gadget');time.sleep(.3);test('empty RB cannot create a grenade or negative ammunition',lambda d:local_pawn(d)['mercGrenades']==0 and not live(server(d)))
 pad(0,'role');pad(0,'role');test('practice role switching preserves depleted grenade supply',lambda d:not local_pawn(d)['spy'] and local_pawn(d)['mercGrenades']==0)
 stop();start(4)
 test('both mercs have independent two-grenade supplies on every client',lambda d:len(d['worlds'])==4 and all_stock(d,1,2) and all_stock(d,3,2),25)
 action(2,'place_terminal');action(1,'place_open');time.sleep(.6);pad(1,'gadget');pad(1,'gadget')
 test('remote RB and rapid repeat spend only one grenade during cooldown',lambda d:all_stock(d,1,1) and all_stock(d,3,2) and all(len(live(w))==1 and live(w)[0]['thrown'] and live(w)[0]['ownerId']==player(d,1)['playerId'] for w in d['worlds']))
 test('remote thrown grenade bounces on the authoritative server',lambda d:any(g['bounces']>0 for g in live(server(d))),3)
 test('all clients remove remote grenade after detonation',lambda d:all(not live(w) for w in d['worlds']),6)
 action(1,'grenade_blocked_release');time.sleep(.6);pad(1,'gadget');time.sleep(.7)
 test('near-wall release is rejected without spending shared ammunition',lambda d:all_stock(d,1,1) and all(not live(w) for w in d['worlds']))
 action(2,'place_terminal');action(1,'place_open');time.sleep(.5);pad(1,'y');pad(1,'gadget')
 test('remote merc can throw last grenade with weapon holstered',lambda d:all_stock(d,1,0) and synced(d,1,lambda p:p['equipment']['weapon']==0) and all(len(live(w))==1 for w in d['worlds']))
 test('last remote grenade expires cleanly',lambda d:all(not live(w) for w in d['worlds']),6)
 pad(1,'gadget');test('empty remote request never creates extra grenades',lambda d:all_stock(d,1,0) and all(not live(w) for w in d['worlds']))
 grab();pad(1,'gadget');test('grabbed merc cannot throw even by pressing RB',lambda d:all_stock(d,1,0) and all(not live(w) for w in d['worlds']))
 extended();test('throwing all grenades makes spy choose kick fallback',lambda d:synced(d,2,lambda p:p['finisher']==2) and all_stock(d,1,0),3)
 pad(2,'b');action(1,'damage');merc_ready()
 action(2,'place_terminal');action(1,'place_open');time.sleep(.5);pad(1,'gadget');test('merc throw leaves one charge for spy theft',lambda d:all_stock(d,1,1))
 test('pre-theft throw finishes its fuse',lambda d:all(not live(w) for w in d['worlds']),6)
 grab();pad(1,'gadget');test('grabbed merc with ammunition cannot throw or deny spy theft',lambda d:all_stock(d,1,1) and all(not live(w) for w in d['worlds']));extended();test('spy sees remaining supply and selects grenade finisher',lambda d:synced(d,2,lambda p:p['finisher']==3),3)
 test('spy theft spends the exact remaining thrown-grenade inventory',lambda d:all_stock(d,1,0) and all(any(not g['thrown'] for g in live(w)) for w in d['worlds']))
 test('stolen grenade still completes its finisher',lambda d:synced(d,1,lambda p:p['health']==0) and synced(d,2,lambda p:p['health']==100),10)
 merc_ready();action(2,'place_terminal');action(1,'place_open');time.sleep(.5);pad(1,'gadget');test('blast fixture receives a real thrown grenade',lambda d:len(live(server(d)))==1);assert 'Existing thrown grenade' in action(1,'grenade_stop_open')
 test('thrown grenade blast damages exposed spy on all clients',lambda d:synced(d,2,lambda p:p['health']==0),6)
 test('exposed spy respawns after grenade damage',lambda d:synced(d,2,lambda p:p['health']==100),15)
 pad(1,'gadget');test('cover fixture receives a real thrown grenade',lambda d:len(live(server(d)))==1);assert 'Existing thrown grenade' in action(1,'grenade_stop_cover');test('covered grenade remains an actual thrown explosive',lambda d:all(any(g['thrown'] for g in live(w)) for w in d['worlds']))
 test('cover test grenade detonates',lambda d:all(not live(w) for w in d['worlds']),6)
 test('solid partition blocks grenade blast damage',lambda d:synced(d,2,lambda p:p['health']==100) and all_stock(d,1,0))
 action(1,'damage');pad(1,'gadget');test('dead merc cannot throw grenades',lambda d:synced(d,1,lambda p:p['health']==0) and all(not live(w) for w in d['worlds']))
 merc_ready();action(0,'duel_open');time.sleep(.5);pad(2,'y');time.sleep(.8);pad(2,'rt')
 test('merc stunned for grenade restriction check',lambda d:synced(d,1,lambda p:p['equipment']['stunned']))
 pad(1,'gadget');test('stunned merc cannot spend or throw a grenade',lambda d:all_stock(d,1,2) and all(not live(w) for w in d['worlds']))
 test('stun expires',lambda d:synced(d,1,lambda p:not p['equipment']['stunned']),6)
 action(0,'network_lag');action(2,'place_terminal');action(1,'place_open');time.sleep(.8);pad(1,'gadget')
 test('one throw and shared stock agree under 100ms lag and packet loss',lambda d:all_stock(d,1,1) and all(len(live(w))==1 and live(w)[0]['thrown'] for w in d['worlds']),5)
 action(1,'damage');test('live grenade survives its throwers death',lambda d:synced(d,1,lambda p:p['health']==0) and all(len(live(w))==1 for w in d['worlds']),3)
 test('orphaned thrown grenade still detonates under latency',lambda d:all(not live(w) for w in d['worlds']),8)
 merc_ready();action(0,'network_reset');action(2,'place_terminal');action(1,'place_open');time.sleep(.6);pad(1,'gadget');action(0,'expire')
 test('round reset restores both merc supplies and removes prior explosives',lambda d:all(w['phase']==1 and not live(w) for w in d['worlds']) and all_stock(d,1,2) and all_stock(d,3,2),20)
 print(json.dumps({'passed':len(results),'total':len(results)}),flush=True)
finally:
 stop();start(1);action(0,'automation_off')
